using System.IdentityModel.Tokens.Jwt;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using LifeVerse.Api.Data;
using Microsoft.EntityFrameworkCore;

namespace LifeVerse.Api.Modules.Worlds;

public sealed record CreateIslandRequest(string Name, string Slug, bool IsPublic, string? Description = null, string? Category = null, int Size = 256, int MaxPlayers = 64);
public sealed record UpdateIslandRequest(string Name, string? Description, string? CoverImageUrl, string? Category, bool IsPublic, int Size, int MaxPlayers, float SpawnX, float SpawnY, float SpawnZ, string? EnvironmentJson, string? ResourceLimitsJson);
public sealed record IslandResponse(Guid Id, Guid OwnerUserId, string Name, string Slug, string Description, string? CoverImageUrl, string Category, bool IsPublic, int Size, int MaxPlayers, float SpawnX, float SpawnY, float SpawnZ, string RuntimeState, long SnapshotVersion, DateTimeOffset CreatedAt, DateTimeOffset UpdatedAt);
public sealed record IslandEntryResponse(string Token, string Host, int Port, DateTimeOffset ExpiresAt, int ProtocolVersion);
public sealed record IslandPermissionRequest(string Permission, string PrincipalType, Guid? UserId, Guid? GroupId);
public sealed record IslandPermissionResponse(Guid Id, string Permission, string PrincipalType, Guid? UserId, Guid? GroupId, DateTimeOffset CreatedAt);
public sealed record IslandSnapshotRequest(string TerrainJson, string? EnvironmentJson, string Operation, long ExpectedVersion);
public sealed record IslandSnapshotResponse(Guid IslandId, long Version, string TerrainJson, string EnvironmentJson, string IntegrityHash, DateTimeOffset CreatedAt);

public static class WorldEndpoints
{
    private static readonly string[] PermissionNames = ["enter", "build", "edit", "delete", "run_scripts", "edit_terrain", "invite", "expel", "ban", "admin"];
    public static IEndpointRouteBuilder MapWorldEndpoints(this IEndpointRouteBuilder endpoints)
    {
        var group = endpoints.MapGroup("/api/v1/worlds").WithTags("Worlds");
        group.MapGet("/templates", () => Results.Ok(new[] { new { slug = "lifeverse-plaza", name = "LifeVerse Plaza", category = "social", description = "Praça pública com caminhos, árvores, iluminação e áreas sociais." }, new { slug = "tropical-island", name = "Tropical Island", category = "nature", description = "Praia tropical com vegetação, água e relevo." }, new { slug = "sandbox-island", name = "Sandbox Island", category = "sandbox", description = "Terreno destinado à construção livre." } }));
        group.MapPost("/islands/{islandId:guid}/ensure-instance", EnsureInstanceAsync).RequireAuthorization();
        group.MapGet("/islands", ListAsync); group.MapGet("/islands/{islandId:guid}", GetAsync); group.MapPost("/islands", CreateAsync).RequireAuthorization(); group.MapPut("/islands/{islandId:guid}", UpdateAsync).RequireAuthorization(); group.MapDelete("/islands/{islandId:guid}", DeleteAsync).RequireAuthorization();
        group.MapGet("/islands/{islandId:guid}/permissions", PermissionsAsync).RequireAuthorization(); group.MapPost("/islands/{islandId:guid}/permissions", GrantPermissionAsync).RequireAuthorization(); group.MapDelete("/islands/{islandId:guid}/permissions/{permissionId:guid}", RevokePermissionAsync).RequireAuthorization();
        group.MapGet("/islands/{islandId:guid}/snapshot", SnapshotAsync).RequireAuthorization(); group.MapPut("/islands/{islandId:guid}/snapshot", SaveSnapshotAsync).RequireAuthorization(); group.MapPost("/islands/{islandId:guid}/entry-token", RequestEntryAsync).RequireAuthorization();
        return endpoints;
    }
    private static async Task<IResult> EnsureInstanceAsync(Guid islandId, HttpContext context, LifeVerseDbContext db, WorldManager manager, CancellationToken ct)
    {
        if (!GetUserId(context, out var userId)) return Results.Unauthorized(); var island = await db.Islands.AsNoTracking().SingleOrDefaultAsync(x => x.Id == islandId && x.DeletedAt == null, ct); if (island is null) return Results.NotFound(); if (!await CanAsync(db, island, userId, "enter", ct)) return Results.Forbid(); var decision = await manager.EnsureAsync(islandId, ct); return decision is null ? Results.NotFound() : decision.State == "running" ? Results.Ok(decision) : Results.Accepted($"/api/v1/worlds/islands/{islandId}/ensure-instance", decision);
    }
    private static async Task<IResult> ListAsync(LifeVerseDbContext db, CancellationToken ct) => Results.Ok(await db.Islands.AsNoTracking().Where(x => x.DeletedAt == null && x.IsPublic).OrderBy(x => x.Name).Select(x => new IslandResponse(x.Id, x.OwnerUserId, x.Name, x.Slug, x.Description, x.CoverImageUrl, x.Category, x.IsPublic, x.Size, x.MaxPlayers, x.SpawnX, x.SpawnY, x.SpawnZ, x.RuntimeState, x.SnapshotVersion, x.CreatedAt, x.UpdatedAt)).ToListAsync(ct));
    private static async Task<IResult> GetAsync(Guid islandId, LifeVerseDbContext db, CancellationToken ct) { var island = await db.Islands.AsNoTracking().SingleOrDefaultAsync(x => x.Id == islandId && x.DeletedAt == null, ct); return island is null ? Results.NotFound() : Results.Ok(ToResponse(island)); }
    private static async Task<IResult> CreateAsync(CreateIslandRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct)
    {
        if (!GetUserId(context, out var owner)) return Results.Unauthorized(); var slug = request.Slug.Trim().ToLowerInvariant(); var name = request.Name.Trim(); var errors = new Dictionary<string, string[]>(); if (name.Length is < 3 or > 80) errors["name"] = ["Name must contain 3-80 characters."]; if (slug.Length is < 3 or > 80 || slug.Any(c => !char.IsLetterOrDigit(c) && c != '-')) errors["slug"] = ["Slug must contain lowercase letters, numbers, or hyphens."]; if (request.Size is < 32 or > 4096) errors["size"] = ["Size must be between 32 and 4096."]; if (request.MaxPlayers is < 1 or > 256) errors["maxPlayers"] = ["MaxPlayers must be between 1 and 256."]; if (errors.Count > 0) return Results.ValidationProblem(errors); if (await db.Islands.AnyAsync(x => x.Slug == slug && x.DeletedAt == null, ct)) return Results.Conflict(); var now = clock.GetUtcNow(); var description = (request.Description ?? string.Empty).Trim(); var island = new Island { Id = Guid.NewGuid(), OwnerUserId = owner, Name = name, Slug = slug, Description = description[..Math.Min(description.Length, 4000)], Category = string.IsNullOrWhiteSpace(request.Category) ? "social" : request.Category.Trim().ToLowerInvariant(), IsPublic = request.IsPublic, Size = request.Size, MaxPlayers = request.MaxPlayers, CreatedAt = now, UpdatedAt = now, RuntimeState = "suspended" }; db.Islands.Add(island); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/worlds/islands/{island.Id}", ToResponse(island));
    }
    private static async Task<IResult> UpdateAsync(Guid islandId, UpdateIslandRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct)
    {
        if (!GetUserId(context, out var userId)) return Results.Unauthorized(); var island = await db.Islands.SingleOrDefaultAsync(x => x.Id == islandId && x.DeletedAt == null, ct); if (island is null) return Results.NotFound(); if (!await CanAsync(db, island, userId, "admin", ct)) return Results.Forbid(); if (string.IsNullOrWhiteSpace(request.Name) || request.Name.Trim().Length > 80 || request.Size is < 32 or > 4096 || request.MaxPlayers is < 1 or > 256) return Results.ValidationProblem(new Dictionary<string, string[]> { ["island"] = ["Invalid island settings."] }); var description = (request.Description ?? string.Empty).Trim(); var cover = request.CoverImageUrl?.Trim(); island.Name = request.Name.Trim(); island.Description = description[..Math.Min(description.Length, 4000)]; island.CoverImageUrl = cover?[..Math.Min(cover.Length, 1024)]; island.Category = (request.Category ?? "social").Trim().ToLowerInvariant(); island.IsPublic = request.IsPublic; island.Size = request.Size; island.MaxPlayers = request.MaxPlayers; island.SpawnX = request.SpawnX; island.SpawnY = Math.Clamp(request.SpawnY, 0, 10000); island.SpawnZ = request.SpawnZ; island.EnvironmentJson = ValidJson(request.EnvironmentJson, "{}"); island.ResourceLimitsJson = ValidJson(request.ResourceLimitsJson, "{}"); island.UpdatedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.Ok(ToResponse(island));
    }
    private static async Task<IResult> DeleteAsync(Guid islandId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!GetUserId(context, out var userId)) return Results.Unauthorized(); var island = await db.Islands.SingleOrDefaultAsync(x => x.Id == islandId && x.DeletedAt == null, ct); if (island is null) return Results.NotFound(); if (!await CanAsync(db, island, userId, "admin", ct)) return Results.Forbid(); island.DeletedAt = clock.GetUtcNow(); island.RuntimeState = "deleted"; await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static async Task<IResult> PermissionsAsync(Guid islandId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!GetUserId(context, out var userId)) return Results.Unauthorized(); var island = await db.Islands.AsNoTracking().SingleOrDefaultAsync(x => x.Id == islandId && x.DeletedAt == null, ct); if (island is null) return Results.NotFound(); if (!await CanAsync(db, island, userId, "admin", ct)) return Results.Forbid(); return Results.Ok(await db.IslandPermissions.AsNoTracking().Where(x => x.IslandId == islandId && x.RevokedAt == null).Select(x => new IslandPermissionResponse(x.Id, x.Permission, x.PrincipalType, x.UserId, x.GroupId, x.CreatedAt)).ToListAsync(ct)); }
    private static async Task<IResult> GrantPermissionAsync(Guid islandId, IslandPermissionRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!GetUserId(context, out var granter)) return Results.Unauthorized(); var island = await db.Islands.SingleOrDefaultAsync(x => x.Id == islandId && x.DeletedAt == null, ct); if (island is null) return Results.NotFound(); if (!await CanAsync(db, island, granter, "admin", ct)) return Results.Forbid(); if (!PermissionNames.Contains(request.Permission) || request.PrincipalType is not ("user" or "group") || (request.PrincipalType == "user" ? request.UserId is null : request.GroupId is null)) return Results.ValidationProblem(new Dictionary<string, string[]> { ["permission"] = ["Invalid permission or principal."] }); var item = new IslandPermission { Id = Guid.NewGuid(), IslandId = islandId, Permission = request.Permission, PrincipalType = request.PrincipalType, UserId = request.UserId, GroupId = request.GroupId, GrantedByUserId = granter, CreatedAt = clock.GetUtcNow() }; db.IslandPermissions.Add(item); await db.SaveChangesAsync(ct); return Results.Ok(new IslandPermissionResponse(item.Id, item.Permission, item.PrincipalType, item.UserId, item.GroupId, item.CreatedAt)); }
    private static async Task<IResult> RevokePermissionAsync(Guid islandId, Guid permissionId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!GetUserId(context, out var userId)) return Results.Unauthorized(); var island = await db.Islands.SingleOrDefaultAsync(x => x.Id == islandId && x.DeletedAt == null, ct); if (island is null) return Results.NotFound(); if (!await CanAsync(db, island, userId, "admin", ct)) return Results.Forbid(); await db.IslandPermissions.Where(x => x.Id == permissionId && x.IslandId == islandId && x.RevokedAt == null).ExecuteUpdateAsync(x => x.SetProperty(p => p.RevokedAt, clock.GetUtcNow()), ct); return Results.NoContent(); }
    private static async Task<IResult> SnapshotAsync(Guid islandId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!GetUserId(context, out var userId)) return Results.Unauthorized(); var island = await db.Islands.AsNoTracking().SingleOrDefaultAsync(x => x.Id == islandId && x.DeletedAt == null, ct); if (island is null) return Results.NotFound(); if (!await CanAsync(db, island, userId, "enter", ct)) return Results.Forbid(); var snapshot = await db.IslandSnapshots.AsNoTracking().Where(x => x.IslandId == islandId).OrderByDescending(x => x.Version).FirstOrDefaultAsync(ct); return snapshot is null ? Results.Ok(new IslandSnapshotResponse(islandId, 0, "{}", island.EnvironmentJson, "", island.UpdatedAt)) : Results.Ok(new IslandSnapshotResponse(snapshot.IslandId, snapshot.Version, snapshot.TerrainJson, snapshot.EnvironmentJson, snapshot.IntegrityHash, snapshot.CreatedAt)); }
    private static async Task<IResult> SaveSnapshotAsync(Guid islandId, IslandSnapshotRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!GetUserId(context, out var userId)) return Results.Unauthorized(); var island = await db.Islands.SingleOrDefaultAsync(x => x.Id == islandId && x.DeletedAt == null, ct); if (island is null) return Results.NotFound(); if (!await CanAsync(db, island, userId, "edit_terrain", ct)) return Results.Forbid(); if (request.TerrainJson.Length > 4_000_000 || !JsonValid(request.TerrainJson)) return Results.ValidationProblem(new Dictionary<string, string[]> { ["terrainJson"] = ["Terrain payload must be valid JSON and <= 4 MB."] }); if (request.ExpectedVersion != island.SnapshotVersion) return Results.Conflict(new { expectedVersion = request.ExpectedVersion, currentVersion = island.SnapshotVersion }); var now = clock.GetUtcNow(); var version = island.SnapshotVersion + 1; var environment = ValidJson(request.EnvironmentJson, island.EnvironmentJson); var hash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes($"{islandId}:{version}:{request.TerrainJson}:{environment}"))); db.IslandSnapshots.Add(new IslandSnapshot { Id = Guid.NewGuid(), IslandId = islandId, Version = version, TerrainJson = request.TerrainJson, EnvironmentJson = environment, IntegrityHash = hash, CreatedAt = now }); db.IslandChanges.Add(new IslandChange { Id = Guid.NewGuid(), IslandId = islandId, Version = version, ActorUserId = userId, Operation = request.Operation[..Math.Min(request.Operation.Length, 48)], PayloadJson = request.TerrainJson, IntegrityHash = hash, CreatedAt = now }); island.SnapshotVersion = version; island.EnvironmentJson = environment; island.UpdatedAt = now; await db.SaveChangesAsync(ct); return Results.Ok(new IslandSnapshotResponse(islandId, version, request.TerrainJson, environment, hash, now)); }
    private static async Task<IResult> RequestEntryAsync(Guid islandId, HttpContext context, LifeVerseDbContext db, WorldManager world, IslandEntryTokenService tokens, TimeProvider clock, CancellationToken ct) { if (!Guid.TryParse(context.User.FindFirst(JwtRegisteredClaimNames.Sub)?.Value, out var userId) || !Guid.TryParse(context.User.FindFirst("sid")?.Value, out var sessionId)) return Results.Unauthorized(); var now = clock.GetUtcNow(); if (!await db.Sessions.AnyAsync(x => x.Id == sessionId && x.UserId == userId && x.RevokedAt == null && x.ExpiresAt > now, ct)) return Results.Unauthorized(); var island = await db.Islands.AsNoTracking().SingleOrDefaultAsync(x => x.Id == islandId && x.DeletedAt == null, ct); if (island is null) return Results.NotFound(); if (!await IslandAccess.AllowsAsync(db, island, userId, now, ct)) return Results.Forbid(); var user = await db.Users.AsNoTracking().Include(x => x.Avatar).SingleAsync(x => x.Id == userId, ct); if (user.Avatar is null) return Results.Problem(statusCode: 409, title: "Avatar is required before entering an island."); var server = await db.ServerInstances.AsNoTracking().Where(x => x.IslandId == islandId && x.StoppedAt == null && x.Status == "healthy" && x.LastHeartbeatAt > now.AddSeconds(-45)).OrderByDescending(x => x.LastHeartbeatAt).FirstOrDefaultAsync(ct); if (server is null) { var decision = await world.EnsureAsync(islandId, ct); context.Response.Headers.RetryAfter = "5"; return Results.Problem(statusCode: 503, title: "No healthy island server is available.", extensions: new Dictionary<string, object?> { ["state"] = decision?.State ?? "unknown" }); } var issued = tokens.Create(user, user.Avatar, island, sessionId); return Results.Ok(new IslandEntryResponse(issued.Token, server.Hostname, server.Port, issued.Identity.ExpiresAt, issued.Identity.ProtocolVersion)); }
    private static bool GetUserId(HttpContext context, out Guid id) => Guid.TryParse(context.User.FindFirst(JwtRegisteredClaimNames.Sub)?.Value, out id);
    private static async Task<bool> CanAsync(LifeVerseDbContext db, Island island, Guid userId, string permission, CancellationToken ct) => (permission == "enter" && island.IsPublic) || island.OwnerUserId == userId || await db.IslandPermissions.AnyAsync(x => x.IslandId == island.Id && x.UserId == userId && x.Permission == permission && x.RevokedAt == null, ct) || await db.IslandPermissions.AnyAsync(x => x.IslandId == island.Id && x.UserId == userId && x.Permission == "admin" && x.RevokedAt == null, ct);
    private static IslandResponse ToResponse(Island x) => new(x.Id, x.OwnerUserId, x.Name, x.Slug, x.Description, x.CoverImageUrl, x.Category, x.IsPublic, x.Size, x.MaxPlayers, x.SpawnX, x.SpawnY, x.SpawnZ, x.RuntimeState, x.SnapshotVersion, x.CreatedAt, x.UpdatedAt);
    private static bool JsonValid(string value) { try { using var _ = JsonDocument.Parse(value); return true; } catch { return false; } }
    private static string ValidJson(string? value, string fallback) => !string.IsNullOrWhiteSpace(value) && JsonValid(value) ? value : fallback;
}
